from pathlib import Path
import json
R=Path(__file__).resolve().parent
def f(s,t,p,sec,e):return dict(text=t,refs=[dict(source=s,section=sec,pages=p if isinstance(p,list) else [p])],evidence=e)
def a(t,p,sec,e):return f('A',t,p,sec,e)
def b(t,p,sec,e):return f('B',t,p,sec,e)
def u(n,title,scope):return dict(unit=n,title=title,part='기초',scope=scope,learning=[],concepts=[],procedures=[],syntax=[],formulas=[],comparisons=[],terms=[],summary_basis='편집 요약',summary=[],review=[],cheat={},checked_images=[],editor_notes=[])
def group(x,title,items):x['concepts'].append(dict(title=title,items=items));return items
def form(label,expression,ref,note=''):return dict(label=label,expression=expression,refs=ref['refs'],evidence=ref['evidence'],note=note)
def code(label,text,ref):return dict(label=label,code=text,refs=ref['refs'],evidence=ref['evidence'],note=None)
def finish(x,summary,terms,qs,defs,comp,forms=None):
 x['summary']=summary;x['terms']=[dict(term=t,definition=v) for t,v in terms];x['review']=[dict(question=q,answer=v) for q,v in qs]
 x['cheat']=dict(definitions=[dict(term=t,definition=v) for t,v in defs],comparison_title=comp['title'],comparison_headers=comp['headers'],comparison_rows=comp['rows'],formulas=forms or [],syntax=[])
 (R/f'unit_{x["unit"]:02}.json').write_text(json.dumps(x,ensure_ascii=False,indent=2),'utf-8')

